10	int spin_lock_try_acquire(spin_lock_t *lock)
11	{
12	    int try_times;
13	    for(try_times = 0; try_times < MAX_TRY_TIMES; try_times++){
14	        if(lock->status == UNLOCKED)
15	            break;
16	    }
17	
18	    if(lock->status == UNLOCKED)
19	        return TRUE;
20	    else
21	        return FALSE;
22	}
