24	void spin_lock_acquire(spin_lock_t *lock)
25	{
26	    while(!spin_lock_try_acquire(lock)){
27	        do_scheduler();
28	    }
29	    atomic_swap_d((uint64_t)LOCKED, (ptr_t)(&(lock->status)));
30	}
