48	/* initialize all pcb and add them into ready_queue */
49	static void init_pcb()
50	{
51	    int num_tasks; 
52	    
53	    // task1: sched1_tasks
54	    for(num_tasks = 0; num_tasks < num_sched1_tasks; num_tasks++){
55	        pcb[num_tasks].kernel_sp = allocPage(1);
56	        pcb[num_tasks].user_sp = pcb[num_tasks].kernel_sp;
57	        pcb[num_tasks].preempt_count = 0;
58	        list_add(&pcb[num_tasks].list, &ready_queue);
59	        pcb[num_tasks].pid = num_tasks + 1;
60	        pcb[num_tasks].type = sched1_tasks[num_tasks]->type;
61	        pcb[num_tasks].status = TASK_READY;
62	        
63	        init_pcb_stack( pcb[num_tasks].kernel_sp, pcb[num_tasks].user_sp, 
64	                        sched1_tasks[num_tasks]->entry_point, &pcb[num_tasks]); 
65	    }
66	    
67	    //task2: lock_tasks
68	    for(num_tasks = num_sched1_tasks; num_tasks < num_sched1_tasks + num_lock_tasks; num_tasks++){
69	        pcb[num_tasks].kernel_sp = allocPage(1);
70	        pcb[num_tasks].user_sp = pcb[num_tasks].kernel_sp;
71	        pcb[num_tasks].preempt_count = 0;
72	        list_add(&pcb[num_tasks].list, &ready_queue);
73	        pcb[num_tasks].pid = num_tasks + 1;
74	        pcb[num_tasks].type = lock_tasks[num_tasks- num_sched1_tasks]->type;
75	        pcb[num_tasks].status = TASK_READY;
76	        
77	        init_pcb_stack( pcb[num_tasks].kernel_sp, pcb[num_tasks].user_sp, 
78	                        lock_tasks[num_tasks - num_sched1_tasks]->entry_point, &pcb[num_tasks]); 
79	    }
80	
81	    /* initialize `current_running` */
82	    current_running = &pid0_pcb;
83	}
